$t=date ("h:i:s",$c);
echo $t."<br>";
//ajout des minute à l'heure actuelle du système
$c=strtotime("+2 minutes");
$t=date ("h:i:s",$c);
echo $t."<br>";
//ajout mois jours heure minute à la date du
système actuelle
