lignes effacées */
mysql_query('DELETE FROM mytable WHERE id < 10');
printf("Lignes effacées : %d\n",
mysql_affected_rows());
/* avec la clause where qui n'est jamais vraie,
on devrait obtenir 0 */
mysql_query('DELETE FROM mytable WHERE 0');
printf("Lignes effacées : %d\n",
mysql_affected_rows());
